// Passkeys (WebAuthn) in the browser — generated by `soli generate auth --passkeys`.
//
// No dependency. Wires two kinds of element:
//
//   [data-passkey-register]  a form on /passkeys: adds a passkey to the account
//   [data-passkey-login]     the sign-in partial: a button, plus conditional UI
//                            (autofill) when the page has an
//                            <input autocomplete="username webauthn">
//
// The CSRF token comes from <meta name="csrf-token"> when the layout has one,
// otherwise from the element's data-csrf-token, and goes out as X-CSRF-Token.
(function () {
  "use strict";

  if (window.__soliPasskeys) return;
  window.__soliPasskeys = true;

  function toBuffer(base64url) {
    var base64 = base64url.replace(/-/g, "+").replace(/_/g, "/");
    while (base64.length % 4) base64 += "=";
    var binary = atob(base64);
    var bytes = new Uint8Array(binary.length);
    for (var i = 0; i < binary.length; i++) bytes[i] = binary.charCodeAt(i);
    return bytes.buffer;
  }

  function toBase64url(buffer) {
    var bytes = new Uint8Array(buffer);
    var binary = "";
    for (var i = 0; i < bytes.length; i++) binary += String.fromCharCode(bytes[i]);
    return btoa(binary).replace(/\+/g, "-").replace(/\//g, "_").replace(/=+$/, "");
  }

  function descriptors(list) {
    return (list || []).map(function (item) {
      return Object.assign({}, item, { id: toBuffer(item.id) });
    });
  }

  // JSON options -> what navigator.credentials wants. Browsers with the
  // WebAuthn L3 parse helpers do it themselves.
  function creationOptions(json) {
    if (PublicKeyCredential.parseCreationOptionsFromJSON) {
      return PublicKeyCredential.parseCreationOptionsFromJSON(json);
    }
    return Object.assign({}, json, {
      challenge: toBuffer(json.challenge),
      user: Object.assign({}, json.user, { id: toBuffer(json.user.id) }),
      excludeCredentials: descriptors(json.excludeCredentials)
    });
  }

  function requestOptions(json) {
    if (PublicKeyCredential.parseRequestOptionsFromJSON) {
      return PublicKeyCredential.parseRequestOptionsFromJSON(json);
    }
    return Object.assign({}, json, {
      challenge: toBuffer(json.challenge),
      allowCredentials: descriptors(json.allowCredentials)
    });
  }

  // PublicKeyCredential -> the JSON the server verifies.
  function credentialJSON(credential) {
    if (typeof credential.toJSON === "function") return credential.toJSON();
    var response = credential.response;
    var json = {
      id: credential.id,
      rawId: toBase64url(credential.rawId),
      type: credential.type,
      authenticatorAttachment: credential.authenticatorAttachment || null,
      clientExtensionResults: credential.getClientExtensionResults(),
      response: { clientDataJSON: toBase64url(response.clientDataJSON) }
    };
    if (response.attestationObject) {
      json.response.attestationObject = toBase64url(response.attestationObject);
      json.response.transports = response.getTransports ? response.getTransports() : [];
    } else {
      json.response.authenticatorData = toBase64url(response.authenticatorData);
      json.response.signature = toBase64url(response.signature);
      json.response.userHandle = response.userHandle ? toBase64url(response.userHandle) : null;
    }
    return json;
  }

  function csrfToken(root) {
    var meta = document.querySelector('meta[name="csrf-token"]');
    return (meta && meta.content) || root.getAttribute("data-csrf-token") || "";
  }

  function post(root, url, body) {
    return fetch(url, {
      method: "POST",
      credentials: "same-origin",
      headers: {
        "Content-Type": "application/json",
        Accept: "application/json",
        "X-CSRF-Token": csrfToken(root)
      },
      body: JSON.stringify(body || {})
    }).then(function (response) {
      return response.json().catch(function () { return {}; }).then(function (json) {
        if (!response.ok) throw new Error(json.error || "Request failed (" + response.status + ")");
        return json;
      });
    });
  }

  function showError(root, error) {
    var slot = root.querySelector("[data-passkey-error]") || document.querySelector("[data-passkey-error]");
    // The user closing the browser prompt is not an error worth showing.
    if (!slot || (error && error.name === "NotAllowedError") || (error && error.name === "AbortError")) return;
    slot.textContent = error && error.message ? error.message : String(error);
    slot.classList.remove("hidden");
  }

  function supported() {
    return !!(window.PublicKeyCredential && navigator.credentials);
  }

  function wireRegistration(form) {
    var root = form.closest("[data-passkeys]") || form;
    form.addEventListener("submit", function (event) {
      event.preventDefault();
      if (!supported()) return showError(root, new Error("This browser does not support passkeys."));
      var name = form.elements.name ? form.elements.name.value : "";
      post(root, "/passkeys/options")
        .then(function (options) {
          return navigator.credentials.create({ publicKey: creationOptions(options) });
        })
        .then(function (credential) {
          return post(root, "/passkeys", { credential: credentialJSON(credential), name: name });
        })
        .then(function () { window.location.reload(); })
        .catch(function (error) { showError(root, error); });
    });
  }

  function wireLogin(root) {
    var pending = null;

    function signIn(conditional) {
      if (pending) pending.abort();
      var controller = new AbortController();
      pending = controller;
      return post(root, "/passkeys/login/options")
        .then(function (options) {
          var request = { publicKey: requestOptions(options), signal: controller.signal };
          if (conditional) request.mediation = "conditional";
          return navigator.credentials.get(request);
        })
        .then(function (credential) {
          return post(root, "/passkeys/login", credentialJSON(credential));
        })
        .then(function (result) { window.location.assign(result.redirect || "/"); })
        .catch(function (error) { showError(root, error); });
    }

    var button = root.querySelector("[data-passkey-login-button]");
    if (button) {
      button.addEventListener("click", function () {
        if (!supported()) return showError(root, new Error("This browser does not support passkeys."));
        signIn(false);
      });
    }

    // Conditional UI: the browser lists passkeys in the email field's autofill.
    if (
      supported() &&
      PublicKeyCredential.isConditionalMediationAvailable &&
      document.querySelector('input[autocomplete~="webauthn"]')
    ) {
      PublicKeyCredential.isConditionalMediationAvailable().then(function (available) {
        if (available) signIn(true);
      });
    }
  }

  function start() {
    document.querySelectorAll("[data-passkey-register]").forEach(wireRegistration);
    document.querySelectorAll("[data-passkey-login]").forEach(wireLogin);
  }

  if (document.readyState === "loading") {
    document.addEventListener("DOMContentLoaded", start);
  } else {
    start();
  }
})();
